943	// paginateSearchResults slices results for the requested client-side page,
944	// normalizing limit and page, and returns the page slice (never nil) plus the
945	// normalized pagination values.
946	func paginateSearchResults(results []search.Result, limit, page int) (pageResults []search.Result, total, totalPages, normLimit, normPage int) {
947		if limit <= 0 {
948			limit = resultsPerPage
949		}
950		total = len(results)
951		totalPages = (total + limit - 1) / limit
952		if totalPages < 1 {
953			totalPages = 1
954		}
955		if page < 1 {
956			page = 1
957		}
958		start := (page - 1) * limit
959		end := start + limit
960		if start < total {
961			if end > total {
962				end = total
963			}
964			pageResults = results[start:end]
965		}
966		if pageResults == nil {
967			pageResults = []search.Result{}
968		}
969		return pageResults, total, totalPages, limit, page
970	}
971	
972	// writeSearchJSON writes client-side paginated search results as JSON.
973	func writeSearchJSON(w io.Writer, resp *search.Response, limit, page int) error {
974		pageResults, total, totalPages, limit, page := paginateSearchResults(resp.Results, limit, page)
975	
976		out := struct {
977			Results    []search.Result    `json:"results"`
978			Total      int                `json:"total"`
979			Page       int                `json:"page"`
980			TotalPages int                `json:"total_pages"`
981			Limit      int                `json:"limit"`
982			Counts     *search.TypeCounts `json:"counts,omitempty"`
983		}{
984			Results:    pageResults,
